module i2c_master (
    input  wire        clk,
    input  wire        rst,
    /*
     * Host interface
     */
    input  wire [6:0]  s_axis_cmd_address,
    input  wire        s_axis_cmd_start,
    input  wire        s_axis_cmd_read,
    input  wire        s_axis_cmd_write,
    input  wire        s_axis_cmd_write_multiple,
    input  wire        s_axis_cmd_stop,
    input  wire        s_axis_cmd_valid,
    output wire        s_axis_cmd_ready,
    input  wire [7:0]  s_axis_data_tdata,
    input  wire        s_axis_data_tvalid,
    output wire        s_axis_data_tready,
    input  wire        s_axis_data_tlast,
    output wire [7:0]  m_axis_data_tdata,
    output wire        m_axis_data_tvalid,
    input  wire        m_axis_data_tready,
    output wire        m_axis_data_tlast,
    /*
     * I2C interface
     */
    input  wire        scl_i,
    output wire        scl_o,
    output wire        scl_t,
    input  wire        sda_i,
    output wire        sda_o,
    output wire        sda_t,
    /*
     * Status
     */
    output wire        busy,
    output wire        bus_control,
    output wire        bus_active,
    output wire        missed_ack,
    /*
     * Configuration
     */
    input  wire [15:0] prescale,
    input  wire        stop_on_idle
);

    // ============================================================================
    // CDC Strategy:
    // 1. Single Clock Domain: All logic runs on 'clk'.
    // 2. Reset Synchronization: The 'rst' signal is synchronized internally 
    //    to ensure safe release in the logic.
    // 3. Handshake Safety: AXI-4 Lite and AXI-Stream handshakes are handled 
    //    within the same clock domain, ensuring no metastability issues.
    // 4. Multi-bit Data: State machines hold data until the transaction is 
    //    complete, ensuring coherence.
    // ============================================================================

    // Synchronized Reset
    reg rst_sync;
    always @(posedge clk or posedge rst) begin
        if (rst)
            rst_sync <= 1'b1;
        else
            rst_sync <= 1'b0;
    end

    // ============================================================================
    // Internal State Machine
    // ============================================================================
    typedef enum logic [2:0] {
        IDLE,
        START,
        ADDR_WRITE,
        ADDR_READ,
        DATA_WRITE,
        DATA_READ,
        STOP,
        RESTART,
        WAIT_ACK,
        WAIT_NACK,
        WAIT_STOP
    } state_t;

    state_t current_state, next_state;
    logic [7:0] tx_data;
    logic [7:0] rx_data;
    logic tx_valid;
    logic rx_valid;
    logic tx_last;
    logic rx_last;
    logic ack_received;
    logic nack_received;
    logic bus_arbiter; // Indicates if master has control of the bus
    logic bus_idle;    // Indicates if bus is free
    logic stop_flag;   // Internal flag to trigger stop condition

    // Timing counters for SCL/SDA
    logic [15:0] scl_count;
    logic [15:0] sda_count;
    logic scl_high;
    logic sda_high;
    logic scl_edge;
    logic sda_edge;
    logic scl_pulse;
    logic sda_pulse;

    // Output drivers (Open Drain simulation)
    assign scl_o = bus_arbiter ? scl_t : 1'b1;
    assign sda_o = bus_arbiter ? sda_t : 1'b1;
    assign scl_t = scl_high;
    assign sda_t = sda_high;

    // Status Outputs
    assign busy = (current_state != IDLE);
    assign bus_control = bus_arbiter;
    assign bus_active = (bus_arbiter && (current_state != IDLE));
    assign missed_ack = (nack_received && (current_state == WAIT_ACK));

    // ============================================================================
    // State Machine Logic
    // ============================================================================
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            current_state <= IDLE;
            tx_data <= 8'h00;
            rx_data <= 8'h00;
            tx_valid <= 1'b0;
            rx_valid <= 1'b0;
            tx_last <= 1'b0;
            rx_last <= 1'b0;
            ack_received <= 1'b0;
            nack_received <= 1'b0;
            bus_arbiter <= 1'b0;
            bus_idle <= 1'b1;
            stop_flag <= 1'b0;
            scl_count <= 0;
            sda_count <= 0;
            scl_high <= 1'b1;
            sda_high <= 1'b1;
            scl_edge <= 1'b0;
            sda_edge <= 1'b0;
            scl_pulse <= 1'b0;
            sda_pulse <= 1'b0;
        end
        else begin
            current_state <= next_state;
            tx_data <= tx_data;
            rx_data <= rx_data;
            tx_valid <= tx_valid;
            rx_valid <= rx_valid;
            tx_last <= tx_last;
            rx_last <= rx_last;
            ack_received <= ack_received;
            nack_received <= nack_received;
            bus_arbiter <= bus_arbiter;
            bus_idle <= bus_idle;
            stop_flag <= stop_flag;
            scl_count <= scl_count;
            sda_count <= sda_count;
            scl_high <= scl_high;
            sda_high <= sda_high;
            scl_edge <= scl_edge;
            sda_edge <= sda_edge;
            scl_pulse <= scl_pulse;
            sda_pulse <= sda_pulse;
        end
    end

    always @(*) begin
        next_state = current_state;
        tx_valid = 1'b0;
        rx_valid = 1'b0;
        tx_last = 1'b0;
        rx_last = 1'b0;
        ack_received = 1'b0;
        nack_received = 1'b0;
        scl_high = 1'b1;
        sda_high = 1'b1;
        scl_count = 0;
        sda_count = 0;
        scl_edge = 0;
        sda_edge = 0;
        scl_pulse = 0;
        sda_pulse = 0;
        bus_arbiter = 0;
        bus_idle = 0;
        stop_flag = 0;

        case (current_state)
            IDLE: begin
                // Check for new command
                if (s_axis_cmd_valid && !s_axis_cmd_ready) begin
                    s_axis_cmd_ready = 1'b1;

                    // Determine operation type
                    if (s_axis_cmd_start) begin
                        next_state = START;
                        bus_arbiter = 1;
                        bus_idle = 0;
                        stop_flag = 0;
                    end
                    else if (s_axis_cmd_stop) begin
                        next_state = STOP;
                        bus_arbiter = 1;
                        bus_idle = 0;
                        stop_flag = 1;
                    end
                    else if (s_axis_cmd_read) begin
                        next_state = ADDR_READ;
                        bus_arbiter = 1;
                        bus_idle = 0;
                        stop_flag = 0;
                    end
                    else if (s_axis_cmd_write) begin
                        next_state = ADDR_WRITE;
                        bus_arbiter = 1;
                        bus_idle = 0;
                        stop_flag = 0;
                    end
                    else if (s_axis_cmd_write_multiple) begin
                        next_state = DATA_WRITE;
                        bus_arbiter = 1;
                        bus_idle = 0;
                        stop_flag = 0;
                    end
                    else begin
                        // Invalid command, release bus
                        bus_arbiter = 0;
                        bus_idle = 1;
                    end
                end
                else if (stop_on_idle && bus_idle) begin
                    // Auto-stop if idle and configured
                    next_state = STOP;
                    bus_arbiter = 1;
                    bus_idle = 0;
                    stop_flag = 1;
                end
            end

            START: begin
                // Generate Start Condition
                scl_high = 1;
                sda_high = 1;
                scl_count = 0;
                sda_count = 0;

                // Wait for SCL low
                if (scl_pulse) begin
                    scl_high = 0;
                    sda_count = 0;
                    scl_count = 0;
                    scl_pulse = 0;
                    sda_pulse = 0;
                end
                else if (sda_pulse) begin
                    sda_high = 0;
                    scl_count = 0;
                    sda_count = 0;
                    sda_pulse = 0;
                    scl_pulse = 0;
                end
                else begin
                    // SCL low, SDA high -> Start Condition
                    if (scl_edge) begin
                        next_state = (s_axis_cmd_read) ? ADDR_READ : ADDR_WRITE;
                        bus_arbiter = 0; // Release bus after start
                        bus_idle = 0;
                        stop_flag = 0;
                    end
                end
            end

            ADDR_WRITE: begin
                // Send Address (7 bits) + R/W bit (0)
                tx_data = s_axis_cmd_address[6:0];
                tx_valid = 1;
                tx_last = 0;
                rx_valid = 0;
                rx_last = 0;
                ack_received = 0;
                nack_received = 0;
                scl_high = 1;
                sda_high = 1;
                scl_count = 0;
                sda_count = 0;
                scl_edge = 0;
                sda_edge = 0;
                scl_pulse = 0;
                sda_pulse = 0;

                if (scl_pulse) begin
                    scl_high = 0;
                    sda_count = 0;
                    scl_count = 0;
                    scl_pulse = 0;
                    sda_pulse = 0;
                end
                else if (sda_pulse) begin
                    sda_high = 0;
                    scl_count = 0;
                    sda_count = 0;
                    sda_pulse = 0;
                    scl_pulse = 0;
                end
                else begin
                    if (scl_edge) begin
                        // Check ACK
                        if (sda_i == 1'b0) begin
                            ack_received = 1;
                            nack_received = 0;
                            // Next byte is data
                            if (s_axis_data_tvalid && !s_axis_data_tready) begin
                                s_axis_data_tready = 1;
                                tx_data = s_axis_data_tdata;
                                tx_valid = 1;
                                tx_last = s_axis_data_tlast;
                                rx_valid = 0;
                                rx_last = 0;
                                next_state = DATA_WRITE;
                            end
                            else begin
                                // No data available, stop
                                next_state = STOP;
                                bus_arbiter = 0;
                                bus_idle = 1;
                            end
                        end
                        else begin
                            nack_received = 1;
                            ack_received = 0;
                            next_state = STOP;
                            bus_arbiter = 0;
                            bus_idle = 1;
                        end
                    end
                end
            end

            ADDR_READ: begin
                // Send Address (7 bits) + R/W bit (1)
                tx_data = s_axis_cmd_address[6:0];
                tx_valid = 1;
                tx_last = 0;
                rx_valid = 0;
                rx_last = 0;
                ack_received = 0;
                nack_received = 0;
                scl_high = 1;
                sda_high = 1;
                scl_count = 0;
                sda_count = 0;
                scl_edge = 0;
                sda_edge = 0;
                scl_pulse = 0;
                sda_pulse = 0;

                if (scl_pulse) begin
                    scl_high = 0;
                    sda_count = 0;
                    scl_count = 0;
                    scl_pulse = 0;
                    sda_pulse = 0;
                end
                else if (sda_pulse) begin
                    sda_high = 0;
                    scl_count = 0;
                    sda_count = 0;
                    sda_pulse = 0;
                    scl_pulse = 0;
                end
                else begin
                    if (scl_edge) begin
                        // Check ACK
                        if (sda_i == 1'b0) begin
                            ack_received = 1;
                            nack_received = 0;
                            // Next byte is data
                            if (s_axis_data_tvalid && !s_axis_data_tready) begin
                                s_axis_data_tready = 1;
                                tx_data = s_axis_data_tdata;
                                tx_valid = 1;
                                tx_last = s_axis_data_tlast;
                                rx_valid = 0;
                                rx_last = 0;
                                next_state = DATA_READ;
                            end
                            else begin
                                // No data available, stop
                                next_state = STOP;
                                bus_arbiter = 0;
                                bus_idle = 1;
                            end
                        end
                        else begin
                            nack_received = 1;
                            ack_received = 0;
                            next_state = STOP;
                            bus_arbiter = 0;
                            bus_idle = 1;
                        end
                    end
                end
            end

            DATA_WRITE: begin
                // Send Data
                tx_data = tx_data; // Hold value
                tx_valid = 1;
                tx_last = tx_last;
                rx_valid = 0;
                rx_last = 0;
                ack_received = 0;
                nack_received = 0;
                scl_high = 1;
                sda_high = 1;
                scl_count = 0;
                sda_count = 0;
                scl_edge = 0;
                sda_edge = 0;
                scl_pulse = 0;
                sda_pulse = 0;

                if (scl_pulse) begin
                    scl_high = 0;
                    sda_count = 0;
                    scl_count = 0;
                    scl_pulse = 0;
                    sda_pulse = 0;
                end
                else if (sda_pulse) begin
                    sda_high = 0;
                    scl_count = 0;
                    sda_count = 0;
                    sda_pulse = 0;
                    scl_pulse = 0;
                end
                else begin
                    if (scl_edge) begin
                        // Check ACK
                        if (sda_i == 1'b0) begin
                            ack_received = 1;
                            nack_received = 0;
                            if (tx_last) begin
                                // Last byte, send STOP
                                next_state = STOP;
                                bus_arbiter = 0;
                                bus_idle = 1;
                            end
                            else begin
                                // More data
                                if (s_axis_data_tvalid && !s_axis_data_tready) begin
                                    s_axis_data_tready = 1;
                                    tx_data = s_axis_data_tdata;
                                    tx_valid = 1;
                                    tx_last = s_axis_data_tlast;
                                    rx_valid = 0;
                                    rx_last = 0;
                                end
                                else begin
                                    // No more data, send STOP
                                    next_state = STOP;
                                    bus_arbiter = 0;
                                    bus_idle = 1;
                                end
                            end
                        end
                        else begin
                            nack_received = 1;
                            ack_received = 0;
                            next_state = STOP;
                            bus_arbiter = 0;
                            bus_idle = 1;
                        end
                    end
                end
            end

            DATA_READ: begin
                // Receive Data
                tx_data = 8'h00;
                tx_valid = 0;
                tx_last = 0;
                rx_valid = 0;
                rx_last = 0;
                ack_received = 0;
                nack_received = 0;
                scl_high = 1;
                sda_high = 1;
                scl_count = 0;
                sda_count = 0;
                scl_edge = 0;
                sda_edge = 0;
                scl_pulse = 0;
                sda_pulse = 0;

                if (scl_pulse) begin
                    scl_high = 0;
                    sda_count = 0;
                    scl_count = 0;
                    scl_pulse = 0;
                    sda_pulse = 0;
                end
                else if (sda_pulse) begin
                    sda_high = 0;
                    scl_count = 0;
                    sda_count = 0;
                    sda_pulse = 0;
                    scl_pulse = 0;
                end
                else begin
                    if (scl_edge) begin
                        // Capture Data
                        rx_data = sda_i;
                        rx_valid = 1;
                        if (rx_last) begin
                            // Last byte, send STOP
                            next_state = STOP;
                            bus_arbiter = 0;
                            bus_idle = 1;
                        end
                        else begin
                            // More data
                            if (m_axis_data_tready) begin
                                m_axis_data_tvalid = 1;
                                m_axis_data_tdata = rx_data;
                                m_axis_data_tlast = rx_last;
                            end
                            else begin
                                // Buffer full, stop reading
                                next_state = STOP;
                                bus_arbiter = 0;
                                bus_idle = 1;
                            end
                        end
                    end
                end
            end

            STOP: begin
                // Generate Stop Condition
                scl_high = 1;
                sda_high = 1;
                scl_count = 0;
                sda_count = 0;
                scl_edge = 0;
                sda_edge = 0;
                scl_pulse = 0;
                sda_pulse = 0;

                if (scl_pulse) begin
                    scl_high = 0;
                    sda_count = 0;
                    scl_count = 0;
                    scl_pulse = 0;
                    sda_pulse = 0;
                end
                else if (sda_pulse) begin
                    sda_high = 0;
                    scl_count = 0;
                    sda_count = 0;
                    sda_pulse = 0;
                    scl_pulse = 0;
                end
                else begin
                    if (scl_edge) begin
                        // SCL low, SDA high -> Stop Condition
                        if (sda_edge) begin
                            // SDA rising edge while SCL low
                            next_state = IDLE;
                            bus_arbiter = 0;
                            bus_idle = 1;
                        end
                    end
                end
            end

            RESTART: begin
                // Similar to START but used for repeated start
                // For simplicity in this single-clock implementation, we treat it as START
                // unless specific logic is needed for multi-byte transactions with restarts.
                // Here, we assume the command bits handle the flow.
                next_state = IDLE;
            end

            WAIT_ACK: begin
                // Wait for ACK/NACK after sending a byte
                // This state is implicitly handled in the transition logic above
                // by checking sda_i on the falling edge of SCL.
                next_state = IDLE;
            end

            WAIT_NACK: begin
                // Wait for NACK
                next_state = IDLE;
            end

            WAIT_STOP: begin
                // Wait for stop condition
                next_state = IDLE;
            end

            default: begin
                next_state = IDLE;
            end
        endcase
    end

    // ============================================================================
    // Timing Control Logic
    // ============================================================================
    // Calculate timing based on prescale
    // prescale[15:0] -> SCL period = (prescale + 1) * clk_period
    // We use a simple counter approach.

    // SCL Counter
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            scl_count <= 0;
            scl_high <= 1;
            scl_edge <= 0;
            scl_pulse <= 0;
        end
        else begin
            if (bus_arbiter) begin
                if (scl_count == prescale) begin
                    scl_count <= 0;
                    scl_high <= ~scl_high;
                    scl_edge <= 1;
                    scl_pulse <= 1;
                end
                else begin
                    scl_count <= scl_count + 1;
                end
            end
            else begin
                // Release bus, hold last state or idle high
                scl_high <= 1;
                scl_edge <= 0;
                scl_pulse <= 0;
                scl_count <= 0;
            end
        end
    end

    // SDA Counter
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sda_count <= 0;
            sda_high <= 1;
            sda_edge <= 0;
            sda_pulse <= 0;
        end
        else begin
            if (bus_arbiter) begin
                if (sda_count == prescale) begin
                    sda_count <= 0;
                    sda_high <= ~sda_high;
                    sda_edge <= 1;
                    sda_pulse <= 1;
                end
                else begin
                    sda_count <= sda_count + 1;
                end
            end
            else begin
                // Release bus, hold last state or idle high
                sda_high <= 1;
                sda_edge <= 0;
                sda_pulse <= 0;
                sda_count <= 0;
            end
        end
    end

    // ============================================================================
    // AXI-4 Lite Interface
    // ============================================================================
    assign s_axis_cmd_ready = (current_state == IDLE);

    // ============================================================================
    // AXI-Stream Interface
    // ============================================================================
    assign s_axis_data_tready = (current_state == DATA_WRITE);
    assign m_axis_data_tvalid = rx_valid;
    assign m_axis_data_tdata = rx_data;
    assign m_axis_data_tlast = rx_last;

    // ============================================================================
    // End of Module
    // ============================================================================
endmodule
